def beat(number, headline, text, visual="photo", asset="bread", kind=None, data=None, sources=()):
    row = {"id": f"e{number:02}", "headline": headline, "text": text,
           "visual": visual, "assetTag": asset, "sourceIds": list(sources)}
    if kind:
        row["kind"] = kind
        row["data"] = data or {}
    return row


